#!/usr/bin/env python3
"""
Round 199o (culprits), 14 October 2026. Needs round 198o.

Showing box widens, reorders and turns kinds off; Raise figures in the Layers box; shoreline glow; muted default colours.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 199o (14 October)\n\nNeeds round 198o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Showing box (asked 14 October): widened or narrowed by a handle on its\n  right edge (#legend-widen, kept on the page body since the box rewrites\n  itself; double-click puts it back); its layers listed in drawing order,\n  top first, and dragged above or below each other (legendDrag, which calls\n  moveRow as the layers box does); "Turn off all Points / Shapes / National\n  highlights" turns off every layer of that kind that is on (kindAllOff).\n- Raise figures as heights moved from 3D terrain to the Layers box, under\n  Shading where points crowd, its description behind an i (liftIntoTools).\n- Bioluminescent: the depth rings and the wash over the shallows are gone\n  (they read as green over the oceans); only a thin blue glow along shores\n  stays, with lake edges and rivers in blue.\n- Faster map: "Every layer and basemap stays/is still here" taken out.\n- Layer colours: a Muted theme (each layer\'s hue kept, greyed toward slate\n  and steel) is the default, set once over the old saved setting\n  (culprits-theme-199o); As drawn and the others stay in Layer colours.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round199o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 198o" not in h.read_text(encoding="utf-8"):
        sys.exit("round199o: round 198o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round199o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/test.mjs", check=False)
            sys.exit("round199o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round199o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
